-- Checkpoint two: leased workers, fenced delivery and recovery by reclaim.
-- Every command is a pure transition over persistent state, so earlier
-- observation values can never see later updates.
import Data.List (..)
import Data.Foldable (..)
import Data.String (..)
import Data.Result (..)
import Domain (..)
import Service (..)

pub fn new_leased(workflow : LeasedWorkflow) : LeasedSimulator =
  LeasedSimulator { now = 0, workers = map(\(id) -> WorkerState { id = id, up = true }, workflow.workers),
    runs = [], tickets = [], next_ticket = 1, service = new_service(), results = [] }

pub fn leased_snapshot(sim : LeasedSimulator) : LeasedSnapshot =
  LeasedSnapshot { now = sim.now, workers = sim.workers, runs = sim.runs }

-- Lease helpers. A lease is live exactly when now < expires.
fn lease_live(now : Int, lease : Option(Lease)) : Bool =
  match lease of
    Some(l) => now < l.expires
    None => false

fn lease_ticket(lease : Option(Lease)) : Int =
  match lease of
    Some(l) => l.ticket
    None => 0

fn expire_lease(now : Int, step : StepState) : StepState =
  match step.lease of
    Some(l) => if step.status == Running then StepState { ..step, lease = Some(Lease { ..l, expires = now }) } else step
    None => step

-- Expire every running lease of a run immediately, keeping ticket/worker visible.
fn expire_running(now : Int, run : RunState) : RunState =
  RunState { ..run, steps = map(\(step) -> expire_lease(now, step), run.steps) }

fn has_running(run : RunState) : Bool = any(\(step) -> step.status == Running, run.steps)

-- Structural updates.
fn replace_step(run : RunState, replacement : StepState) : RunState =
  RunState { ..run, steps = map(\(step) -> if step.id == replacement.id then replacement else step, run.steps) }

fn replace_run(sim : LeasedSimulator, replacement : RunState) : LeasedSimulator =
  LeasedSimulator { ..sim, runs = map(\(run) -> if run.id == replacement.id then replacement else run, sim.runs) }

fn replace_ticket(sim : LeasedSimulator, replacement : Ticket) : LeasedSimulator =
  LeasedSimulator { ..sim, tickets = map(\(t) -> if t.id == replacement.id then replacement else t, sim.tickets) }

fn set_worker(sim : LeasedSimulator, id : String, up : Bool) : LeasedSimulator =
  LeasedSimulator { ..sim, workers = map(\(w) -> if w.id == id then WorkerState { ..w, up = up } else w, sim.workers) }

fn mark_pending(run : RunState, status : StepStatus) : RunState =
  RunState { ..run, steps = map(\(step) -> if step.status == Pending then StepState { ..step, status = status } else step, run.steps) }

-- Lookups and runtime validation, in the published precedence.
fn find_run(sim : LeasedSimulator, id : String) : Option(RunState) =
  find(\(run) -> run.id == id, sim.runs)

fn find_step(run : RunState, id : String) : Option(StepState) =
  find(\(step) -> step.id == id, run.steps)

fn find_definition(workflow : LeasedWorkflow, id : String) : Option(StepDefinition) =
  find(\(definition) -> definition.id == id, workflow.steps)

fn find_worker(sim : LeasedSimulator, id : String) : Option(WorkerState) =
  find(\(w) -> w.id == id, sim.workers)

fn worker_up(sim : LeasedSimulator, id : String) : Bool =
  match find_worker(sim, id) of
    Some(w) => w.up
    None => false

fn require_worker(sim : LeasedSimulator, id : String) : Result(WorkerState, String) =
  match find_worker(sim, id) of
    Some(w) => Ok(w)
    None => Err("UNKNOWN_WORKER")

fn require_up(sim : LeasedSimulator, id : String) : Result(WorkerState, String) =
  let w = require_worker(sim, id)?
  if w.up then Ok(w) else Err("WORKER_DOWN")

fn find_ticket(sim : LeasedSimulator, id : Int) : Option(Ticket) =
  find(\(t) -> t.id == id, sim.tickets)

-- Ownership means the ticket's original worker, even after another worker reclaims.
fn require_owned_ticket(sim : LeasedSimulator, worker : String, id : Int) : Result(Ticket, String) =
  match find_ticket(sim, id) of
    None => Err("UNKNOWN_TICKET")
    Some(t) => if t.worker == worker then Ok(t) else Err("WRONG_WORKER")

fn ticket_step(sim : LeasedSimulator, ticket : Ticket) : Option((RunState, StepState)) =
  match find_run(sim, ticket.run_id) of
    None => None
    Some(run) =>
      match find_step(run, ticket.step_id) of
        None => None
        Some(step) => Some((run, step))

-- Fencing: a ticket acts only while it is the step's current, live lease.
fn current_live(sim : LeasedSimulator, ticket : Ticket) : Bool =
  match ticket_step(sim, ticket) of
    None => false
    Some(pair) =>
      let step = snd(pair)
      step.status == Running && lease_ticket(step.lease) == ticket.id && lease_live(sim.now, step.lease)

fn held_by(now : Int, worker : String, step : StepState) : Bool =
  match step.lease of
    Some(l) => step.status == Running && l.worker == worker && now < l.expires
    None => false

fn worker_busy(sim : LeasedSimulator, worker : String) : Bool =
  any(\(run) -> any(\(step) -> held_by(sim.now, worker, step), run.steps), sim.runs)

-- Scheduling: expired running work first (any nonterminal run), then ready pending work.
fn deps_succeeded(run : RunState, definition : StepDefinition) : Bool =
  all(\(dep) -> any(\(s) -> s.id == dep && s.status == Succeeded, run.steps), definition.needs)

fn select_step(now : Int, expired : Bool, run : RunState, states : List(StepState), definitions : List(StepDefinition)) : Option(Action) =
  match (states, definitions) of
    (Cons(step, more_states), Cons(definition, more_definitions)) =>
      let ready =
        if expired then step.status == Running && not(lease_live(now, step.lease))
        else run.status == RunActive && step.status == Pending && step.ready_at <= now && deps_succeeded(run, definition)
      if ready then Some(Action { run = run, step = step, definition = definition })
      else select_step(now, expired, run, more_states, more_definitions)
    _ => None

fn select_run(now : Int, expired : Bool, runs : List(RunState), definitions : List(StepDefinition)) : Option(Action) =
  match runs of
    Nil => None
    Cons(run, rest) =>
      match select_step(now, expired, run, run.steps, definitions) of
        Some(action) => Some(action)
        None => select_run(now, expired, rest, definitions)

fn select_work(sim : LeasedSimulator, workflow : LeasedWorkflow) : Option(Action) =
  match select_run(sim.now, true, sim.runs, workflow.steps) of
    Some(action) => Some(action)
    None => select_run(sim.now, false, sim.runs, workflow.steps)

fn claim(sim : LeasedSimulator, workflow : LeasedWorkflow, worker : String) : Result((LeasedSimulator, CommandResult), String) =
  let _ = require_up(sim, worker)?
  if worker_busy(sim, worker) then Err("WORKER_BUSY")
  else
    match select_work(sim, workflow) of
      None => Ok((sim, RTicket(None)))
      Some(action) =>
        let expires = sim.now + workflow.lease_duration
        if expires > time_limit() then Err("TIME_OVERFLOW")
        else
          let id = sim.next_ticket
          let lease = Some(Lease { worker = worker, ticket = id, expires = expires })
          -- A new attempt begins durably; a reclaim keeps the attempt number.
          let running =
            if action.step.status == Pending then
              StepState { ..action.step, status = Running, attempts = action.step.attempts + 1, lease = lease }
            else StepState { ..action.step, lease = lease }
          let kind = if action.run.status == RunActive then ExecuteCall else LookupCall
          let ticket = Ticket { id = id, worker = worker, run_id = action.run.id, step_id = running.id,
            attempt = running.attempts, kind = kind, response = None, delivered = false }
          let claimed = replace_run(sim, replace_step(action.run, running))
          Ok((LeasedSimulator { ..claimed, tickets = append(claimed.tickets, [ticket]), next_ticket = id + 1 }, RTicket(Some(id))))

fn renew(sim : LeasedSimulator, workflow : LeasedWorkflow, worker : String, id : Int) : Result((LeasedSimulator, CommandResult), String) =
  let _ = require_up(sim, worker)?
  let ticket = require_owned_ticket(sim, worker, id)?
  if not(current_live(sim, ticket)) then Ok((sim, RRenewed(false)))
  else
    let expires = sim.now + workflow.lease_duration
    if expires > time_limit() then Err("TIME_OVERFLOW")
    else
      match ticket_step(sim, ticket) of
        None => Ok((sim, RRenewed(false)))
        Some(pair) =>
          let step = snd(pair)
          let renewed = StepState { ..step, lease = Some(Lease { worker = ticket.worker, ticket = ticket.id, expires = expires }) }
          Ok((replace_run(sim, replace_step(fst(pair), renewed)), RRenewed(true)))

-- Call: the first live call invokes the mock once and saves the receipt; later calls replay it.
fn call(sim : LeasedSimulator, workflow : LeasedWorkflow, worker : String, id : Int) : Result((LeasedSimulator, CommandResult), String) =
  let _ = require_up(sim, worker)?
  let ticket = require_owned_ticket(sim, worker, id)?
  if not(current_live(sim, ticket)) then Ok((sim, RStale))
  else
    match ticket.response of
      Some(outcome) => Ok((sim, RReceipt(ticket.kind, outcome)))
      None =>
        match find_definition(workflow, ticket.step_id) of
          None => Err("INVALID_INPUT")
          Some(definition) =>
            let key = ActionKey { run_id = ticket.run_id, step_id = ticket.step_id }
            let response =
              if ticket.kind == ExecuteCall then
                execute_as(sim.service, Some(worker), Some(ticket.id), key, definition.amount, ticket.attempt, definition.failures)
              else lookup_as(sim.service, Some(worker), Some(ticket.id), key, ticket.attempt)
            let outcome = snd(response)
            let saved = replace_ticket(LeasedSimulator { ..sim, service = fst(response) }, Ticket { ..ticket, response = Some(outcome) })
            Ok((saved, RReceipt(ticket.kind, outcome)))

-- Commit a delivered response to the durable run state.
fn commit(sim : LeasedSimulator, workflow : LeasedWorkflow, run : RunState, step : StepState, kind : CallKind, outcome : CallOutcome) : Result(RunState, String) =
  if kind == LookupCall then
    let cancelling = run.status == RunCancelling
    let status = if outcome == Found then Succeeded elif cancelling then Cancelled else Blocked
    let reconciled = replace_step(run, StepState { ..step, status = status })
    if has_running(reconciled) then Ok(reconciled)
    else Ok(RunState { ..reconciled, status = if cancelling then RunCancelled else RunFailed })
  elif outcome == Transient then
    if step.attempts < workflow.max_attempts then
      let deadline = sim.now + workflow.retry_delay
      if deadline > time_limit() then Err("TIME_OVERFLOW")
      else Ok(replace_step(run, StepState { ..step, status = Pending, ready_at = deadline }))
    else
      -- Budget exhausted: block pending work and drain any other in-flight branch by lookup.
      let failed = mark_pending(replace_step(run, StepState { ..step, status = Failed }), Blocked)
      if has_running(failed) then Ok(RunState { ..expire_running(sim.now, failed), status = RunFailing })
      else Ok(RunState { ..failed, status = RunFailed })
  else
    let completed = replace_step(run, StepState { ..step, status = Succeeded })
    if run.status == RunActive && all(\(s) -> s.status == Succeeded, completed.steps) then
      Ok(RunState { ..completed, status = RunSucceeded })
    else Ok(completed)

fn deliver(sim : LeasedSimulator, workflow : LeasedWorkflow, id : Int) : Result((LeasedSimulator, CommandResult), String) =
  match find_ticket(sim, id) of
    None => Err("UNKNOWN_TICKET")
    Some(ticket) =>
      match ticket.response of
        None => Ok((sim, RCommitted(false)))
        Some(outcome) =>
          if ticket.delivered || not(current_live(sim, ticket)) || not(worker_up(sim, ticket.worker)) then
            Ok((sim, RCommitted(false)))
          else
            match ticket_step(sim, ticket) of
              None => Ok((sim, RCommitted(false)))
              Some(pair) =>
                let cleared = StepState { ..snd(pair), lease = None }
                let committed = commit(sim, workflow, fst(pair), cleared, ticket.kind, outcome)?
                let updated = replace_ticket(replace_run(sim, committed), Ticket { ..ticket, delivered = true })
                Ok((updated, RCommitted(true)))

-- First cancellation revokes every running execute lease; later ones are no-ops.
fn cancel(sim : LeasedSimulator, run : RunState) : LeasedSimulator =
  if run.status == RunActive then
    let cancelled = expire_running(sim.now, mark_pending(run, Cancelled))
    let status = if has_running(cancelled) then RunCancelling else RunCancelled
    replace_run(sim, RunState { ..cancelled, status = status, cancel_requested = true })
  else sim

fn new_run(sim : LeasedSimulator, workflow : LeasedWorkflow, id : String) : Result(LeasedSimulator, String) =
  if any(\(run) -> run.id == id, sim.runs) then Err("DUPLICATE_RUN")
  else
    let steps = map(\(definition) ->
      StepState { id = definition.id, status = Pending, attempts = 0, ready_at = sim.now, lease = None }, workflow.steps)
    let run = RunState { id = id, status = RunActive, cancel_requested = false, steps = steps }
    Ok(LeasedSimulator { ..sim, runs = append(sim.runs, [run]) })

pub fn apply_leased(sim : LeasedSimulator, workflow : LeasedWorkflow, command : LeasedCommand) : Result((LeasedSimulator, CommandResult), String) =
  match command of
    LStart(id) =>
      let started = new_run(sim, workflow, id)?
      Ok((started, RNull))
    LAdvance(by) =>
      if sim.now + by > time_limit() then Err("TIME_OVERFLOW")
      else Ok((LeasedSimulator { ..sim, now = sim.now + by }, RNull))
    LObserve => Ok((sim, RSnapshot(leased_snapshot(sim))))
    LCrash(worker) =>
      let w = require_worker(sim, worker)?
      if not(w.up) then Err("WORKER_DOWN") else Ok((set_worker(sim, worker, false), RNull))
    LRestart(worker) =>
      let w = require_worker(sim, worker)?
      if w.up then Err("WORKER_UP") else Ok((set_worker(sim, worker, true), RNull))
    LClaim(worker) => claim(sim, workflow, worker)
    LRenew(worker, id) => renew(sim, workflow, worker, id)
    LCall(worker, id) => call(sim, workflow, worker, id)
    LDeliver(id) => deliver(sim, workflow, id)
    LCancel(id) =>
      match find_run(sim, id) of
        None => Err("UNKNOWN_RUN")
        Some(run) => Ok((cancel(sim, run), RNull))

fn run_leased(sim : LeasedSimulator, workflow : LeasedWorkflow, commands : List(LeasedCommand)) : Result(LeasedSimulator, String) =
  match commands of
    Nil => Ok(sim)
    Cons(command, rest) =>
      let step = apply_leased(sim, workflow, command)?
      let next = fst(step)
      run_leased(LeasedSimulator { ..next, results = append(next.results, [snd(step)]) }, workflow, rest)

pub fn simulate_leased(workflow : LeasedWorkflow) : Result(LeasedSimulator, String) =
  run_leased(new_leased(workflow), workflow, workflow.commands)

import Data.List (..)
import Data.Foldable (..)
import Data.String (..)
import Data.Result (..)
import Data.Maybe (..)
import Json (..)
import Domain (..)
import Runner (snapshot)
import Leased (leased_snapshot)

fn step_status(status : StepStatus) : String =
  match status of
    Pending => "pending"
    Running => "running"
    Succeeded => "succeeded"
    Failed => "failed"
    Blocked => "blocked"
    Cancelled => "cancelled"

fn run_status(status : RunStatus) : String =
  match status of
    RunActive => "active"
    RunSucceeded => "succeeded"
    RunFailed => "failed"
    RunCancelling => "cancelling"
    RunCancelled => "cancelled"
    RunFailing => "failing"

fn step_json(step : StepState) : Json =
  JObj([("id", JStr(step.id)), ("status", JStr(step_status(step.status))),
    ("attempts", JInt(step.attempts)), ("ready_at", JInt(step.ready_at))])

fn run_json(run : RunState) : Json =
  JObj([("id", JStr(run.id)), ("status", JStr(run_status(run.status))),
    ("cancel_requested", JBool(run.cancel_requested)), ("steps", JArr(map(step_json, run.steps)))])

fn snapshot_fields(state : Snapshot) : List((String, Json)) =
  [("now", JInt(state.now)), ("up", JBool(state.up)), ("runs", JArr(map(run_json, state.runs)))]

fn snapshot_json(state : Snapshot) : Json = JObj(snapshot_fields(state))

fn key_json(key : ActionKey) : Json = JArr([JStr(key.run_id), JStr(key.step_id)])

fn call_kind(kind : CallKind) : String =
  match kind of
    ExecuteCall => "execute"
    LookupCall => "lookup"

fn call_outcome(outcome : CallOutcome) : String =
  match outcome of
    Applied => "applied"
    Replayed => "replayed"
    Transient => "transient"
    Found => "found"
    Missing => "missing"

fn call_json(call : ServiceCall) : Json =
  JObj([("kind", JStr(call_kind(call.kind))), ("key", key_json(call.key)),
    ("attempt", JInt(call.attempt)), ("outcome", JStr(call_outcome(call.outcome)))])

fn effect_json(entry : Effect) : Json =
  JObj([("key", key_json(entry.key)), ("amount", JInt(entry.amount))])

pub fn result_json(sim : Simulator) : Json =
  let final_fields = append(snapshot_fields(snapshot(sim)),
    [("calls", JArr(map(call_json, sim.service.calls))), ("effects", JArr(map(effect_json, sim.service.effects)))])
  JObj([("observations", JArr(map(snapshot_json, sim.observations))), ("final", JObj(final_fields))])

-- Leased-mode rendering: steps gain `lease`, calls gain `worker`/`ticket`.
fn lease_json(lease : Option(Lease)) : Json =
  match lease of
    None => JNull
    Some(l) => JObj([("worker", JStr(l.worker)), ("ticket", JInt(l.ticket)), ("expires", JInt(l.expires))])

fn leased_step_json(step : StepState) : Json =
  JObj([("id", JStr(step.id)), ("status", JStr(step_status(step.status))),
    ("attempts", JInt(step.attempts)), ("ready_at", JInt(step.ready_at)), ("lease", lease_json(step.lease))])

fn leased_run_json(run : RunState) : Json =
  JObj([("id", JStr(run.id)), ("status", JStr(run_status(run.status))),
    ("cancel_requested", JBool(run.cancel_requested)), ("steps", JArr(map(leased_step_json, run.steps)))])

fn worker_json(worker : WorkerState) : Json =
  JObj([("id", JStr(worker.id)), ("up", JBool(worker.up))])

fn leased_snapshot_fields(state : LeasedSnapshot) : List((String, Json)) =
  [("now", JInt(state.now)), ("workers", JArr(map(worker_json, state.workers))),
    ("runs", JArr(map(leased_run_json, state.runs)))]

fn leased_call_json(call : ServiceCall) : Json =
  JObj([("worker", JStr(unwrap_or("", call.worker))), ("ticket", JInt(unwrap_or(0, call.ticket))),
    ("kind", JStr(call_kind(call.kind))), ("key", key_json(call.key)),
    ("attempt", JInt(call.attempt)), ("outcome", JStr(call_outcome(call.outcome)))])

fn command_result_json(result : CommandResult) : Json =
  match result of
    RNull => JNull
    RTicket(None) => JObj([("ticket", JNull)])
    RTicket(Some(id)) => JObj([("ticket", JInt(id))])
    RRenewed(flag) => JObj([("renewed", JBool(flag))])
    RReceipt(kind, outcome) => JObj([("kind", JStr(call_kind(kind))), ("outcome", JStr(call_outcome(outcome)))])
    RStale => JObj([("outcome", JStr("stale"))])
    RCommitted(flag) => JObj([("committed", JBool(flag))])
    RSnapshot(state) => JObj(leased_snapshot_fields(state))

pub fn leased_result_json(sim : LeasedSimulator) : Json =
  let final_fields = append(leased_snapshot_fields(leased_snapshot(sim)),
    [("calls", JArr(map(leased_call_json, sim.service.calls))), ("effects", JArr(map(effect_json, sim.service.effects)))])
  JObj([("results", JArr(map(command_result_json, sim.results))), ("final", JObj(final_fields))])

pub fn response_json(result : Result(Outcome, String)) : Json =
  match result of
    Ok(LegacyOutcome(sim)) => JObj([("ok", JBool(true)), ("result", result_json(sim))])
    Ok(LeasedOutcome(sim)) => JObj([("ok", JBool(true)), ("result", leased_result_json(sim))])
    Err(code) => JObj([("ok", JBool(false)), ("error", JObj([("code", JStr(code))]))])

import Data.List (..)
import Data.Foldable (..)
import Data.String (..)
import Data.Result (..)
import Domain (..)
import Service (..)

pub fn new_simulator() : Simulator =
  Simulator { now = 0, up = true, runs = [], service = new_service(), observations = [] }

pub fn snapshot(sim : Simulator) : Snapshot =
  -- Persistent values make every historical snapshot independent of later updates.
  Snapshot { now = sim.now, up = sim.up, runs = sim.runs }

fn new_step(now : Int, definition : StepDefinition) : StepState =
  StepState { id = definition.id, status = Pending, attempts = 0, ready_at = now, lease = None }

fn terminal(status : RunStatus) : Bool =
  status == RunSucceeded || status == RunFailed || status == RunCancelled

fn select_step(now : Int, inflight : Bool, run : RunState, states : List(StepState), definitions : List(StepDefinition)) : Option(Action) =
  match (states, definitions) of
    (Cons(step, more_states), Cons(definition, more_definitions)) =>
      let ready =
        if inflight then step.status == Running
        else run.status == RunActive && step.status == Pending && step.ready_at <= now
          && all(\(dep) -> any(\(s) -> s.id == dep && s.status == Succeeded, run.steps), definition.needs)
      if ready then Some(Action { run = run, step = step, definition = definition })
      else select_step(now, inflight, run, more_states, more_definitions)
    _ => None

fn select_run(now : Int, inflight : Bool, runs : List(RunState), definitions : List(StepDefinition)) : Option(Action) =
  match runs of
    Nil => None
    Cons(run, rest) =>
      match select_step(now, inflight, run, run.steps, definitions) of
        Some(action) => Some(action)
        None => select_run(now, inflight, rest, definitions)

pub fn select_action(sim : Simulator, workflow : Workflow) : Option(Action) =
  -- Resume the oldest in-flight attempt before scanning ready pending work.
  match select_run(sim.now, true, sim.runs, workflow.steps) of
    Some(action) => Some(action)
    None => select_run(sim.now, false, sim.runs, workflow.steps)

fn replace_step(run : RunState, replacement : StepState) : RunState =
  RunState { ..run, steps = map(\(step) -> if step.id == replacement.id then replacement else step, run.steps) }

fn replace_run(sim : Simulator, replacement : RunState) : Simulator =
  Simulator { ..sim, runs = map(\(run) -> if run.id == replacement.id then replacement else run, sim.runs) }

fn mark_pending(run : RunState, status : StepStatus) : RunState =
  RunState { ..run, steps = map(\(step) -> if step.status == Pending then StepState { ..step, status = status } else step, run.steps) }

fn find_run(sim : Simulator, id : String) : Option(RunState) =
  find(\(run) -> run.id == id, sim.runs)

-- Commit a successful (applied or replayed) execute response.
fn commit_success(run : RunState, step : StepState) : RunState =
  let completed = replace_step(run, StepState { ..step, status = Succeeded })
  if all(\(s) -> s.status == Succeeded, completed.steps) then RunState { ..completed, status = RunSucceeded }
  else completed

-- Commit a transient execute response: schedule a retry or exhaust the budget.
fn commit_transient(sim : Simulator, workflow : Workflow, run : RunState, step : StepState) : Result(RunState, String) =
  if step.attempts < workflow.max_attempts then
    let deadline = sim.now + workflow.retry_delay
    if deadline > time_limit() then Err("TIME_OVERFLOW")
    else Ok(replace_step(run, StepState { ..step, status = Pending, ready_at = deadline }))
  else
    let failed = replace_step(run, StepState { ..step, status = Failed })
    Ok(RunState { ..mark_pending(failed, Blocked), status = RunFailed })

-- Commit a cancellation lookup: found effects are kept, missing ones are cancelled.
fn commit_lookup(run : RunState, step : StepState, outcome : CallOutcome) : RunState =
  let status = if outcome == Found then Succeeded else Cancelled
  RunState { ..replace_step(run, StepState { ..step, status = status }), status = RunCancelled }

fn crash_now(sim : Simulator) : Simulator = Simulator { ..sim, up = false }

pub fn tick(sim : Simulator, workflow : Workflow, checkpoint : Option(Checkpoint)) : Result(Simulator, String) =
  match select_action(sim, workflow) of
    None => Ok(sim)
    Some(action) =>
      -- Beginning an attempt is durable; a recovered attempt keeps its number and key.
      let running =
        if action.step.status == Pending then
          StepState { ..action.step, status = Running, attempts = action.step.attempts + 1 }
        else action.step
      let begun_run = replace_step(action.run, running)
      let begun = replace_run(sim, begun_run)
      if checkpoint == Some(AfterBegin) then Ok(crash_now(begun))
      else
        let key = ActionKey { run_id = action.run.id, step_id = running.id }
        let reconciling = begun_run.status == RunCancelling
        let response =
          if reconciling then lookup(begun.service, key, running.attempts)
          else execute(begun.service, key, action.definition.amount, running.attempts, action.definition.failures)
        let called = Simulator { ..begun, service = fst(response) }
        let outcome = snd(response)
        -- The service response and effect are atomic; the crash window is before the commit.
        if checkpoint == Some(AfterCall) then Ok(crash_now(called))
        else
          let committed =
            if reconciling then Ok(commit_lookup(begun_run, running, outcome))
            elif outcome == Transient then commit_transient(called, workflow, begun_run, running)
            else Ok(commit_success(begun_run, running))
          let finished = committed?
          Ok(replace_run(called, finished))

fn cancel(sim : Simulator, run : RunState) : Simulator =
  if terminal(run.status) then sim
  else
    let cancelled = mark_pending(run, Cancelled)
    let status = if any(\(step) -> step.status == Running, cancelled.steps) then RunCancelling else RunCancelled
    replace_run(sim, RunState { ..cancelled, status = status, cancel_requested = true })

pub fn apply_command(sim : Simulator, workflow : Workflow, command : Command) : Result(Simulator, String) =
  match command of
    Start(id) =>
      if not(sim.up) then Err("PROCESS_DOWN")
      elif any(\(run) -> run.id == id, sim.runs) then Err("DUPLICATE_RUN")
      else
        let run = RunState { id = id, status = RunActive, cancel_requested = false,
          steps = map(\(definition) -> new_step(sim.now, definition), workflow.steps) }
        Ok(Simulator { ..sim, runs = append(sim.runs, [run]) })
    Tick(checkpoint) =>
      if not(sim.up) then Err("PROCESS_DOWN")
      else tick(sim, workflow, checkpoint)
    Advance(by) =>
      if sim.now + by > time_limit() then Err("TIME_OVERFLOW")
      else Ok(Simulator { ..sim, now = sim.now + by })
    Observe => Ok(Simulator { ..sim, observations = append(sim.observations, [snapshot(sim)]) })
    Crash =>
      if not(sim.up) then Err("PROCESS_DOWN")
      else Ok(crash_now(sim))
    Restart =>
      if sim.up then Err("PROCESS_UP")
      else Ok(Simulator { ..sim, up = true })
    Cancel(id) =>
      if not(sim.up) then Err("PROCESS_DOWN")
      else
        match find_run(sim, id) of
          None => Err("UNKNOWN_RUN")
          Some(run) => Ok(cancel(sim, run))

fn run_commands(sim : Simulator, workflow : Workflow, commands : List(Command)) : Result(Simulator, String) =
  match commands of
    Nil => Ok(sim)
    Cons(command, rest) =>
      let next = apply_command(sim, workflow, command)?
      run_commands(next, workflow, rest)

pub fn simulate(workflow : Workflow) : Result(Simulator, String) =
  run_commands(new_simulator(), workflow, workflow.commands)

import Data.List (..)
import Data.Foldable (..)
import Data.String (..)
import Data.Result (..)
import Domain (..)

pub fn new_service() : MockService = MockService { calls = [], effects = [] }

fn audit(service : MockService, worker : Option(String), ticket : Option(Int), kind : CallKind, key : ActionKey, attempt : Int, outcome : CallOutcome) : MockService =
  MockService { ..service, calls = append(service.calls,
    [ServiceCall { worker = worker, ticket = ticket, kind = kind, key = key, attempt = attempt, outcome = outcome }]) }

fn has_effect(service : MockService, key : ActionKey) : Bool =
  any(\(entry) -> entry.key == key, service.effects)

-- The per-key failure counter is the number of transient execute responses already
-- audited for that key. Lookups never touch it.
fn transient_count(service : MockService, key : ActionKey) : Int =
  count(\(call) -> call.kind == ExecuteCall && call.outcome == Transient && call.key == key, service.calls)

-- Atomic execute: replay an existing effect, fail transiently while the configured
-- failure budget remains, otherwise record exactly one effect. Every call is audited.
-- The worker/ticket pair only labels the audit entry; it never affects the outcome.
pub fn execute_as(service : MockService, worker : Option(String), ticket : Option(Int), key : ActionKey, amount : Int, attempt : Int, failures : Int) : (MockService, CallOutcome) =
  if has_effect(service, key) then
    (audit(service, worker, ticket, ExecuteCall, key, attempt, Replayed), Replayed)
  elif transient_count(service, key) < failures then
    (audit(service, worker, ticket, ExecuteCall, key, attempt, Transient), Transient)
  else
    let applied = MockService { ..service, effects = append(service.effects, [Effect { key = key, amount = amount }]) }
    (audit(applied, worker, ticket, ExecuteCall, key, attempt, Applied), Applied)

-- Atomic lookup: reports whether an effect exists without ever creating one.
pub fn lookup_as(service : MockService, worker : Option(String), ticket : Option(Int), key : ActionKey, attempt : Int) : (MockService, CallOutcome) =
  let outcome = if has_effect(service, key) then Found else Missing
  (audit(service, worker, ticket, LookupCall, key, attempt, outcome), outcome)

-- Legacy (checkpoint-one) entry points: unlabelled calls with identical semantics.
pub fn execute(service : MockService, key : ActionKey, amount : Int, attempt : Int, failures : Int) : (MockService, CallOutcome) =
  execute_as(service, None, None, key, amount, attempt, failures)

pub fn lookup(service : MockService, key : ActionKey, attempt : Int) : (MockService, CallOutcome) =
  lookup_as(service, None, None, key, attempt)

