type StepDefinition = StepDefinition {
  id: String,
  needs: List(String),
  amount: Int,
  failures: Int
}

type Workflow = Workflow {
  steps: List(StepDefinition),
  commands: List(Command),
  max_attempts: Int,
  retry_delay: Int
}

type RunState = RunState {
  id: String,
  status: RunStatus,
  cancel_requested: Bool,
  steps: List(StepState)
}

fn new_leased(workflow : LeasedWorkflow) : LeasedSimulator =
  LeasedSimulator { now = 0, workers = map(\(id) -> WorkerState { id = id, up = true }, workflow.workers),
    runs = [], tickets = [], next_ticket = 1, service = new_service(), results = [] }

fn require_up(sim : LeasedSimulator, id : String) : Result(WorkerState, String) =
  let w = require_worker(sim, id)?
  if w.up then Ok(w) else Err("WORKER_DOWN")

fn current_live(sim : LeasedSimulator, ticket : Ticket) : Bool =
  match ticket_step(sim, ticket) of
    None => false
    Some(pair) =>
      let step = snd(pair)
      step.status == Running && lease_ticket(step.lease) == ticket.id && lease_live(sim.now, step.lease)

fn select_step(now : Int, expired : Bool, run : RunState, states : List(StepState), definitions : List(StepDefinition)) : Option(Action) =
  match (states, definitions) of
    (Cons(step, more_states), Cons(definition, more_definitions)) =>
      let ready =
        if expired then step.status == Running && not(lease_live(now, step.lease))
        else run.status == RunActive && step.status == Pending && step.ready_at <= now && deps_succeeded(run, definition)
      if ready then Some(Action { run = run, step = step, definition = definition })
      else select_step(now, expired, run, more_states, more_definitions)
    _ => None

fn claim(sim : LeasedSimulator, workflow : LeasedWorkflow, worker : String) : Result((LeasedSimulator, CommandResult), String) =
  let _ = require_up(sim, worker)?
  if worker_busy(sim, worker) then Err("WORKER_BUSY")
  else
    match select_work(sim, workflow) of
      None => Ok((sim, RTicket(None)))
      Some(action) =>
        let expires = sim.now + workflow.lease_duration
        if expires > time_limit() then Err("TIME_OVERFLOW")
        else
          let id = sim.next_ticket
          let lease = Some(Lease { worker = worker, ticket = id, expires = expires })
          -- A new attempt begins durably; a reclaim keeps the attempt number.
          let running =
            if action.step.status == Pending then
              StepState { ..action.step, status = Running, attempts = action.step.attempts + 1, lease = lease }
            else StepState { ..action.step, lease = lease }
          let kind = if action.run.status == RunActive then ExecuteCall else LookupCall
          let ticket = Ticket { id = id, worker = worker, run_id = action.run.id, step_id = running.id,
            attempt = running.attempts, kind = kind, response = None, delivered = false }
          let claimed = replace_run(sim, replace_step(action.run, running))
          Ok((LeasedSimulator { ..claimed, tickets = append(claimed.tickets, [ticket]), next_ticket = id + 1 }, RTicket(Some(id))))

fn renew(sim : LeasedSimulator, workflow : LeasedWorkflow, worker : String, id : Int) : Result((LeasedSimulator, CommandResult), String) =
  let _ = require_up(sim, worker)?
  let ticket = require_owned_ticket(sim, worker, id)?
  if not(current_live(sim, ticket)) then Ok((sim, RRenewed(false)))
  else
    let expires = sim.now + workflow.lease_duration
    if expires > time_limit() then Err("TIME_OVERFLOW")
    else
      match ticket_step(sim, ticket) of
        None => Ok((sim, RRenewed(false)))
        Some(pair) =>
          let step = snd(pair)
          let renewed = StepState { ..step, lease = Some(Lease { worker = ticket.worker, ticket = ticket.id, expires = expires }) }
          Ok((replace_run(sim, replace_step(fst(pair), renewed)), RRenewed(true)))

fn call(sim : LeasedSimulator, workflow : LeasedWorkflow, worker : String, id : Int) : Result((LeasedSimulator, CommandResult), String) =
  let _ = require_up(sim, worker)?
  let ticket = require_owned_ticket(sim, worker, id)?
  if not(current_live(sim, ticket)) then Ok((sim, RStale))
  else
    match ticket.response of
      Some(outcome) => Ok((sim, RReceipt(ticket.kind, outcome)))
      None =>
        match find_definition(workflow, ticket.step_id) of
          None => Err("INVALID_INPUT")
          Some(definition) =>
            let key = ActionKey { run_id = ticket.run_id, step_id = ticket.step_id }
            let response =
              if ticket.kind == ExecuteCall then
                execute_as(sim.service, Some(worker), Some(ticket.id), key, definition.amount, ticket.attempt, definition.failures)
              else lookup_as(sim.service, Some(worker), Some(ticket.id), key, ticket.attempt)
            let outcome = snd(response)
            let saved = replace_ticket(LeasedSimulator { ..sim, service = fst(response) }, Ticket { ..ticket, response = Some(outcome) })
            Ok((saved, RReceipt(ticket.kind, outcome)))

fn commit(sim : LeasedSimulator, workflow : LeasedWorkflow, run : RunState, step : StepState, kind : CallKind, outcome : CallOutcome) : Result(RunState, String) =
  if kind == LookupCall then
    let cancelling = run.status == RunCancelling
    let status = if outcome == Found then Succeeded elif cancelling then Cancelled else Blocked
    let reconciled = replace_step(run, StepState { ..step, status = status })
    if has_running(reconciled) then Ok(reconciled)
    else Ok(RunState { ..reconciled, status = if cancelling then RunCancelled else RunFailed })
  elif outcome == Transient then
    if step.attempts < workflow.max_attempts then
      let deadline = sim.now + workflow.retry_delay
      if deadline > time_limit() then Err("TIME_OVERFLOW")
      else Ok(replace_step(run, StepState { ..step, status = Pending, ready_at = deadline }))
    else
      -- Budget exhausted: block pending work and drain any other in-flight branch by lookup.
      let failed = mark_pending(replace_step(run, StepState { ..step, status = Failed }), Blocked)
      if has_running(failed) then Ok(RunState { ..expire_running(sim.now, failed), status = RunFailing })
      else Ok(RunState { ..failed, status = RunFailed })
  else
    let completed = replace_step(run, StepState { ..step, status = Succeeded })
    if run.status == RunActive && all(\(s) -> s.status == Succeeded, completed.steps) then
      Ok(RunState { ..completed, status = RunSucceeded })
    else Ok(completed)

fn cancel(sim : LeasedSimulator, run : RunState) : LeasedSimulator =
  if run.status == RunActive then
    let cancelled = expire_running(sim.now, mark_pending(run, Cancelled))
    let status = if has_running(cancelled) then RunCancelling else RunCancelled
    replace_run(sim, RunState { ..cancelled, status = status, cancel_requested = true })
  else sim

fn new_run(sim : LeasedSimulator, workflow : LeasedWorkflow, id : String) : Result(LeasedSimulator, String) =
  if any(\(run) -> run.id == id, sim.runs) then Err("DUPLICATE_RUN")
  else
    let steps = map(\(definition) ->
      StepState { id = definition.id, status = Pending, attempts = 0, ready_at = sim.now, lease = None }, workflow.steps)
    let run = RunState { id = id, status = RunActive, cancel_requested = false, steps = steps }
    Ok(LeasedSimulator { ..sim, runs = append(sim.runs, [run]) })

fn step_json(step : StepState) : Json =
  JObj([("id", JStr(step.id)), ("status", JStr(step_status(step.status))),
    ("attempts", JInt(step.attempts)), ("ready_at", JInt(step.ready_at))])

fn run_json(run : RunState) : Json =
  JObj([("id", JStr(run.id)), ("status", JStr(run_status(run.status))),
    ("cancel_requested", JBool(run.cancel_requested)), ("steps", JArr(map(step_json, run.steps)))])

fn call_json(call : ServiceCall) : Json =
  JObj([("kind", JStr(call_kind(call.kind))), ("key", key_json(call.key)),
    ("attempt", JInt(call.attempt)), ("outcome", JStr(call_outcome(call.outcome)))])

fn result_json(sim : Simulator) : Json =
  let final_fields = append(snapshot_fields(snapshot(sim)),
    [("calls", JArr(map(call_json, sim.service.calls))), ("effects", JArr(map(effect_json, sim.service.effects)))])
  JObj([("observations", JArr(map(snapshot_json, sim.observations))), ("final", JObj(final_fields))])

fn leased_step_json(step : StepState) : Json =
  JObj([("id", JStr(step.id)), ("status", JStr(step_status(step.status))),
    ("attempts", JInt(step.attempts)), ("ready_at", JInt(step.ready_at)), ("lease", lease_json(step.lease))])

fn leased_run_json(run : RunState) : Json =
  JObj([("id", JStr(run.id)), ("status", JStr(run_status(run.status))),
    ("cancel_requested", JBool(run.cancel_requested)), ("steps", JArr(map(leased_step_json, run.steps)))])

fn leased_snapshot_fields(state : LeasedSnapshot) : List((String, Json)) =
  [("now", JInt(state.now)), ("workers", JArr(map(worker_json, state.workers))),
    ("runs", JArr(map(leased_run_json, state.runs)))]

fn leased_result_json(sim : LeasedSimulator) : Json =
  let final_fields = append(leased_snapshot_fields(leased_snapshot(sim)),
    [("calls", JArr(map(leased_call_json, sim.service.calls))), ("effects", JArr(map(effect_json, sim.service.effects)))])
  JObj([("results", JArr(map(command_result_json, sim.results))), ("final", JObj(final_fields))])

fn snapshot(sim : Simulator) : Snapshot =
  -- Persistent values make every historical snapshot independent of later updates.
  Snapshot { now = sim.now, up = sim.up, runs = sim.runs }

fn select_step(now : Int, inflight : Bool, run : RunState, states : List(StepState), definitions : List(StepDefinition)) : Option(Action) =
  match (states, definitions) of
    (Cons(step, more_states), Cons(definition, more_definitions)) =>
      let ready =
        if inflight then step.status == Running
        else run.status == RunActive && step.status == Pending && step.ready_at <= now
          && all(\(dep) -> any(\(s) -> s.id == dep && s.status == Succeeded, run.steps), definition.needs)
      if ready then Some(Action { run = run, step = step, definition = definition })
      else select_step(now, inflight, run, more_states, more_definitions)
    _ => None

fn commit_success(run : RunState, step : StepState) : RunState =
  let completed = replace_step(run, StepState { ..step, status = Succeeded })
  if all(\(s) -> s.status == Succeeded, completed.steps) then RunState { ..completed, status = RunSucceeded }
  else completed

fn commit_transient(sim : Simulator, workflow : Workflow, run : RunState, step : StepState) : Result(RunState, String) =
  if step.attempts < workflow.max_attempts then
    let deadline = sim.now + workflow.retry_delay
    if deadline > time_limit() then Err("TIME_OVERFLOW")
    else Ok(replace_step(run, StepState { ..step, status = Pending, ready_at = deadline }))
  else
    let failed = replace_step(run, StepState { ..step, status = Failed })
    Ok(RunState { ..mark_pending(failed, Blocked), status = RunFailed })

fn commit_lookup(run : RunState, step : StepState, outcome : CallOutcome) : RunState =
  let status = if outcome == Found then Succeeded else Cancelled
  RunState { ..replace_step(run, StepState { ..step, status = status }), status = RunCancelled }

fn tick(sim : Simulator, workflow : Workflow, checkpoint : Option(Checkpoint)) : Result(Simulator, String) =
  match select_action(sim, workflow) of
    None => Ok(sim)
    Some(action) =>
      -- Beginning an attempt is durable; a recovered attempt keeps its number and key.
      let running =
        if action.step.status == Pending then
          StepState { ..action.step, status = Running, attempts = action.step.attempts + 1 }
        else action.step
      let begun_run = replace_step(action.run, running)
      let begun = replace_run(sim, begun_run)
      if checkpoint == Some(AfterBegin) then Ok(crash_now(begun))
      else
        let key = ActionKey { run_id = action.run.id, step_id = running.id }
        let reconciling = begun_run.status == RunCancelling
        let response =
          if reconciling then lookup(begun.service, key, running.attempts)
          else execute(begun.service, key, action.definition.amount, running.attempts, action.definition.failures)
        let called = Simulator { ..begun, service = fst(response) }
        let outcome = snd(response)
        -- The service response and effect are atomic; the crash window is before the commit.
        if checkpoint == Some(AfterCall) then Ok(crash_now(called))
        else
          let committed =
            if reconciling then Ok(commit_lookup(begun_run, running, outcome))
            elif outcome == Transient then commit_transient(called, workflow, begun_run, running)
            else Ok(commit_success(begun_run, running))
          let finished = committed?
          Ok(replace_run(called, finished))

fn cancel(sim : Simulator, run : RunState) : Simulator =
  if terminal(run.status) then sim
  else
    let cancelled = mark_pending(run, Cancelled)
    let status = if any(\(step) -> step.status == Running, cancelled.steps) then RunCancelling else RunCancelled
    replace_run(sim, RunState { ..cancelled, status = status, cancel_requested = true })

fn apply_command(sim : Simulator, workflow : Workflow, command : Command) : Result(Simulator, String) =
  match command of
    Start(id) =>
      if not(sim.up) then Err("PROCESS_DOWN")
      elif any(\(run) -> run.id == id, sim.runs) then Err("DUPLICATE_RUN")
      else
        let run = RunState { id = id, status = RunActive, cancel_requested = false,
          steps = map(\(definition) -> new_step(sim.now, definition), workflow.steps) }
        Ok(Simulator { ..sim, runs = append(sim.runs, [run]) })
    Tick(checkpoint) =>
      if not(sim.up) then Err("PROCESS_DOWN")
      else tick(sim, workflow, checkpoint)
    Advance(by) =>
      if sim.now + by > time_limit() then Err("TIME_OVERFLOW")
      else Ok(Simulator { ..sim, now = sim.now + by })
    Observe => Ok(Simulator { ..sim, observations = append(sim.observations, [snapshot(sim)]) })
    Crash =>
      if not(sim.up) then Err("PROCESS_DOWN")
      else Ok(crash_now(sim))
    Restart =>
      if sim.up then Err("PROCESS_UP")
      else Ok(Simulator { ..sim, up = true })
    Cancel(id) =>
      if not(sim.up) then Err("PROCESS_DOWN")
      else
        match find_run(sim, id) of
          None => Err("UNKNOWN_RUN")
          Some(run) => Ok(cancel(sim, run))

fn audit(service : MockService, worker : Option(String), ticket : Option(Int), kind : CallKind, key : ActionKey, attempt : Int, outcome : CallOutcome) : MockService =
  MockService { ..service, calls = append(service.calls,
    [ServiceCall { worker = worker, ticket = ticket, kind = kind, key = key, attempt = attempt, outcome = outcome }]) }

fn lookup_as(service : MockService, worker : Option(String), ticket : Option(Int), key : ActionKey, attempt : Int) : (MockService, CallOutcome) =
  let outcome = if has_effect(service, key) then Found else Missing
  (audit(service, worker, ticket, LookupCall, key, attempt, outcome), outcome)

fn fields(value : Json, required : List(String), optional : List(String)) : Result(List((String, Json)), String) =
  match value of
    JObj(pairs) =>
      let keys = map(\(pair) -> fst(pair), pairs)
      let _ = ensure(unique(keys) && all(\(key) -> elem(key, keys), required)
          && all(\(key) -> elem(key, append(required, optional)), keys), "INVALID_INPUT")?
      Ok(pairs)
    _ => Err("INVALID_INPUT")

fn valid_id_bytes(s : String, i : Int) : Bool =
  if i >= byte_len(s) then true
  else
    let c = byte_at(s, i)
    ((c >= 65 && c <= 90) || (c >= 97 && c <= 122)
      || (c >= 48 && c <= 57) || c == 95 || c == 45) && valid_id_bytes(s, i + 1)

fn parse_checkpoint(obj : List((String, Json))) : Result(Option(Checkpoint), String) =
  match find(\(pair) -> fst(pair) == "crash_at", obj) of
    None => Ok(None)
    Some(pair) =>
      match snd(pair) of
        JStr(name) =>
          if name == "after_begin" then Ok(Some(AfterBegin))
          elif name == "after_call" then Ok(Some(AfterCall))
          else Err("INVALID_INPUT")
        _ => Err("INVALID_INPUT")

fn acyclic(remaining : List(StepDefinition), visited : List(String)) : Bool =
  if is_nil(remaining) then true
  else
    let ready = filter(\(step) -> all(\(dep) -> elem(dep, visited), step.needs), remaining)
    if is_nil(ready) then false
    else
      let seen = append(visited, map(\(step) -> step.id, ready))
      acyclic(filter(\(step) -> not(elem(step.id, seen)), remaining), seen)

fn validate_graph(steps : List(StepDefinition)) : Result(Unit, String) =
  let ids = map(\(step) -> step.id, steps)
  let _ = ensure(unique(ids), "DUPLICATE_STEP")?
  let _ = ensure(all(\(step) -> all(\(dep) -> elem(dep, ids), step.needs), steps), "UNKNOWN_DEPENDENCY")?
  ensure(acyclic(steps, []), "DEPENDENCY_CYCLE")
